#!/usr/bin/env python3
"""Materialize V51 hash availability and signal-audit contract 51072404."""
from __future__ import annotations
import base64,json,zlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
PAYLOAD=''
def main():
    files=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)).decode('utf-8'))
    written=[]
    for rel,content in files.items():
        path=ROOT/rel;path.parent.mkdir(parents=True,exist_ok=True);path.write_text(content,encoding='utf-8');written.append(rel)
    bootstrap=ROOT/'reports/V51_BOOTSTRAP_PATHS.txt'
    existing=[]
    if bootstrap.exists():existing=[x.strip() for x in bootstrap.read_text('utf-8').splitlines() if x.strip()]
    for rel in written+['reports/V51_HASH_SIGNAL_AUDIT.json']:
        if rel not in existing:existing.append(rel)
    bootstrap.parent.mkdir(parents=True,exist_ok=True)
    bootstrap.write_text('\n'.join(existing)+'\n',encoding='utf-8')
    print(json.dumps({'version':'51072404','written':written,'bootstrap_count':len(existing)},ensure_ascii=False))
if __name__=='__main__':main()
